"extends CharacterBody3D

# Variables de configuración
@export var velocidad_caminar: float = 3.0
@export var velocidad_correr: float = 5.5
@export var velocidad_rotacion: float = 2.5
@export var municion: int = 15

var esta_apuntando: bool = false
var gravedad: float = ProjectSettings.get_setting(\"physics/3d/default_gravity\")

@onready var raycast_disparo = $RayCast3D # Añade un nodo RayCast3D apuntando hacia adelante

func _physics_process(delta):
	# Aplicar gravedad
	if not is_on_floor():
		velocity.y -= gravedad * delta

	# Obtener entrada (compatible con botones virtuales en pantalla)
	var giro = Input.get_axis(\"girar_derecha\", \"girar_izquierda\")
	var avance = Input.get_axis(\"retroceder\", \"avanzar\")
	var corriendo = Input.is_action_pressed(\"correr\")
	esta_apuntando = Input.is_action_pressed(\"apuntar\")

	# Rotación estilo tanque
	rotate_y(giro * velocidad_rotacion * delta)

	# Movimiento (solo se mueve si no está apuntando, regla clásica de RE)
	if not esta_apuntando:
		var velocidad_actual = velocidad_correr if corriendo else velocidad_caminar
		var direccion = -transform.basis.z * avance
		velocity.x = direccion.x * velocidad_actual
		velocity.z = direccion.z * velocidad_actual
	else:
		velocity.x = 0
		velocity.z = 0
		if Input.is_action_just_pressed(\"disparar\"):
			disparar()

	move_and_slide()

func disparar():
	if municion > 0:
		municion -= 1
		print(\"¡PUM! Munición restante: \", municion)
		if raycast_disparo.is_colliding():
			var objetivo = raycast_disparo.get_collider()
			if objetivo.has_method(\"recibir_dano\"):
				objetivo.recibir_dano(25)
	else:
		print(\"*Click* Sin balas\")

---
This is a build request. Build a complete, playable game now (or apply the requested change to the existing game). Do not ask clarifying questions; make reasonable assumptions and note them briefly when you finish.

Screenshots for your own checks: save small JPEGs (a .jpg path, viewport at most 1280px wide) and read only the latest one; older images are dropped from context. Read a full-size PNG only when fine detail matters.
"

