 for(const g of graves){ctx.save();ctx.translate(g.x,g.y);ctx.rotate(g.a);ctx.scale(g.r,g.r);ctx.fillStyle='#101411';ctx.fillRect(-15,8,32,8);ctx.fillStyle='#4d5349';if(g.kind==='cross'){ctx.fillRect(-3,-20,6,30);ctx.fillRect(-11,-12,22,5)}else{ctx.beginPath();ctx.moveTo(-12,10);ctx.lineTo(-12,-12);ctx.quadraticCurveTo(-12,-22,0,-22);ctx.quadraticCurveTo(12,-22,12,-12);ctx.lineTo(12,10);ctx.closePath();ctx.fill()}ctx.fillStyle='#70715d';ctx.fillRect(-10,-13,4,15);ctx.restore();}
 // blood on stones and the churchyard's broken lanterns
 for(let i=0;i<6;i++){let x=380+i*225,y=i%2?460:1000;ctx.fillStyle='#986a45';ctx.fillRect(x,y,5,21);ctx.fillStyle='#daa657';ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(x+2,y,7,0,TAU);ctx.fill();ctx.globalAlpha=1;}
 // exit flare marks
 ctx.save();ctx.strokeStyle='#d5ee74';ctx.globalAlpha=.24;ctx.lineWidth=2;ctx.beginPath();ctx.arc(960,250,42,0,TAU);ctx.stroke();ctx.fillStyle='#d5ee74';ctx.globalAlpha=.65;ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('SIGNAL 04',960,112);ctx.restore();
}
function drawPickups(time){for(const p of pickups){let bob=Math.sin(time*4+p.pulse)*4;ctx.save();ctx.translate(p.x,p.y+bob);ctx.shadowBlur=18;ctx.shadowColor=p.type==='ammo'?'#d5ee74':'#e66952';ctx.fillStyle=p.type==='ammo'?'#d5ee74':'#e66952';ctx.beginPath();ctx.arc(0,0,9,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#20251d';if(p.type==='ammo'){ctx.fillRect(-4,-2,8,4);ctx.fillRect(-1,-5,2,10)}else{ctx.fillRect(-5,-1,10,2);ctx.fillRect(-1,-5,2,10)}ctx.restore();}}
function drawZombies(time){for(const z of zombies){if(z.dead){ctx.fillStyle='#572d28';ctx.globalAlpha=.75;ctx.beginPath();ctx.ellipse(z.x,z.y+5,z.r*1.1,z.r*.63,z.a,0,TAU);ctx.fill();ctx.globalAlpha=1;continue}ctx.save();ctx.translate(z.x,z.y+Math.sin(z.phase)*1.5);ctx.rotate(z.a);if(z.boss){ctx.fillStyle='#111411';ctx.beginPath();ctx.ellipse(0,8,35,23,0,0,TAU);ctx.fill();ctx.fillStyle=z.hit?'#edb499':'#46493b';ctx.beginPath();ctx.ellipse(0,0,30,18,0,0,TAU);ctx.fill();ctx.fillStyle='#555343';ctx.fillRect(-26,-6,38,12);ctx.fillStyle='#b84437';ctx.beginPath();ctx.arc(6,-6,4,0,TAU);ctx.arc(6,6,4,0,TAU);ctx.fill();ctx.strokeStyle='#252a23';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-13,-10);ctx.lineTo(10,-26);ctx.moveTo(-13,10);ctx.lineTo(10,26);ctx.stroke();}
 else {ctx.fillStyle='#101411';ctx.beginPath();ctx.ellipse(0,6,z.r*1.12,z.r*.68,0,0,TAU);ctx.fill();ctx.fillStyle=z.hit?'#f0b293':z.heavy?'#706956':'#656958';ctx.beginPath();ctx.ellipse(0,0,z.r*.72,z.r,0,0,TAU);ctx.fill();ctx.fillStyle=z.heavy?'#494b3d':'#4c5144';ctx.beginPath();ctx.arc(9,-2,9,0,TAU);ctx.fill();ctx.fillStyle='#a94d3b';ctx.beginPath();ctx.arc(15,-5,2,0,TAU);ctx.arc(15,2,2,0,TAU);ctx.fill();ctx.strokeStyle='#696b57';ctx.lineWidth=5;ctx.lineCap='round';let sway=Math.sin(z.phase)*5;ctx.beginPath();ctx.moveTo(-2,-11);ctx.lineTo(9,-19+sway);ctx.moveTo(-2,11);ctx.lineTo(9,19-sway);ctx.stroke();}
 ctx.restore();if(z.hp<z.max){ctx.fillStyle='#101411';ctx.fillRect(z.x-z.r,z.y-z.r-12,z.r*2,3);ctx.fillStyle=z.boss?'#e66952':'#d5ee74';ctx.fillRect(z.x-z.r,z.y-z.r-12,z.r*2*Math.max(0,z.hp/z.max),3)}}}
function drawPlayer(time){if(!player)return;ctx.save();ctx.translate(player.x,player.y);if(player.invuln>0&&Math.floor(time*18)%2===0)ctx.globalAlpha=.45; // flashlight/aim cone
 let a=player.a;if(aiming){ctx.fillStyle='rgba(215,230,174,.07)';ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,510,a-.12,a+.12);ctx.closePath();ctx.fill();}
 ctx.rotate(a);ctx.fillStyle='#101411';ctx.beginPath();ctx.ellipse(0,6,20,13,0,0,TAU);ctx.fill();ctx.fillStyle='#879078';ctx.beginPath();ctx.ellipse(0,0,15,11,0,0,TAU);ctx.fill();ctx.fillStyle='#555f4a';ctx.fillRect(-4,-9,13,18);ctx.fillStyle='#b9bc9c';ctx.beginPath();ctx.arc(6,-2,6,0,TAU);ctx.fill();ctx.fillStyle='#282d24';ctx.fillRect(6,-3,19,6);ctx.fillStyle='#d5ee74';ctx.fillRect(20,-1.5,6,3);ctx.fillStyle='#e2d6ae';ctx.beginPath();ctx.arc(7,-2,1.3,0,TAU);ctx.fill();ctx.restore();
 if(aiming){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(a);ctx.strokeStyle='#d5ee7490';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(36,0);ctx.lineTo(450,0);ctx.stroke();ctx.restore();}}
function drawBullets(){for(const b of bullets){ctx.fillStyle='#ffe3a0';ctx.shadowBlur=10;ctx.shadowColor='#ffbb63';ctx.beginPath();ctx.arc(b.x,b.y,3,0,TAU);ctx.fill();ctx.shadowBlur=0}}
function drawParticles(){for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,TAU);ctx.fill()}ctx.globalAlpha=1}
function drawScreenFX(){// restrained red damage flash and aim reticle
 if(flash>0){ctx.fillStyle=`rgba(255,215,145,${flash*1.5})`;ctx.fillRect(0,0,cw,ch)}if(player&&aiming&&pointer.inside&&state==='playing'){ctx.strokeStyle='#d5ee74';ctx.globalAlpha=.8;ctx.lineWidth=1;ctx.beginPath();ctx.arc(pointer.x,pointer.y,8,0,TAU);ctx.moveTo(pointer.x-13,pointer.y);ctx.lineTo(pointer.x-5,pointer.y);ctx.moveTo(pointer.x+5,pointer.y);ctx.lineTo(pointer.x+13,pointer.y);ctx.moveTo(pointer.x,pointer.y-13);ctx.lineTo(pointer.x,pointer.y-5);ctx.moveTo(pointer.x,pointer.y+5);ctx.lineTo(pointer.x,pointer.y+13);ctx.stroke();ctx.globalAlpha=1}if(player&&player.hp<32){ctx.fillStyle=`rgba(153,26,18,${(32-player.hp)/130})`;ctx.fillRect(0,0,cw,ch)}}

// Controls: tank movement, hold aim, then fire. Touch uses a virtual steering stick.
function refreshAim(){aiming=pointer.right||keys.has(' ')||touch.aim}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='r')reload();if(k==='escape'||k==='p'){if(state==='playing'||state==='paused')pause()}if(k==='enter'&&(state==='title'||state==='dead'||state==='won'))startGame();refreshAim()});
window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());refreshAim()});
canvas.addEventListener('pointermove',e=>{let r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top;pointer.inside=true;if(e.pointerType==='touch'&&aiming)pointer.down=false});
canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top;pointer.inside=true;if(e.button===2){pointer.right=true;refreshAim()}else if(e.button===0){pointer.down=true;if(aiming)shoot()}if(e.pointerType==='touch'&&aiming){pointer.down=false;shoot()}canvas.setPointerCapture?.(e.pointerId)});
window.addEventListener('pointerup',e=>{if(e.button===0)pointer.down=false;if(e.button===2){pointer.right=false;refreshAim()}});canvas.addEventListener('contextmenu',e=>e.preventDefault());
$('start-btn').addEventListener('click',()=>{if(state==='paused'){pause();return}startGame();$('overlay').classList.remove('end');$('how-btn').style.display='';$('kicker').textContent='NORTH COUNTY · 02:17 AM';$('title').innerHTML='LAST<br><em>LIGHT</em>';$('subtitle').innerHTML='The road is gone. The radio is dead.<br>Something is moving in the dark.';$('story').innerHTML='Four signal flares are burning beyond the cemetery. Reach the chapel and light them all.<br><br>One magazine. A handful of rounds. Make every shot count.'});
$('how-btn').addEventListener('click',()=>{if(state==='title'){$('story').innerHTML='FIELD NOTES<br><br>W / S move forward and back. A / D turn. Hold RIGHT MOUSE or SPACE to aim; click or hold LEFT MOUSE to fire. Press R to reload.<br><br>While aiming you cannot move. Sprint with SHIFT to escape. Collect the glowing supplies. Survive four nights.';$('how-btn').textContent='BACK TO BRIEFING'}else{$('how-btn').textContent='FIELD NOTES';$('story').innerHTML='Four signal flares are burning beyond the cemetery. Reach the chapel and light them all.<br><br>One magazine. A handful of rounds. Make every shot count.'}});
$('pause-btn').addEventListener('click',pause);
$('aim-touch').addEventListener('pointerdown',e=>{e.preventDefault();touch.aim=!touch.aim;refreshAim();$('aim-touch').classList.toggle('active',touch.aim)});
$('run-touch').addEventListener('pointerdown',e=>{e.preventDefault();touch.run=true;$('run-touch').classList.add('active')});window.addEventListener('pointerup',()=>{touch.run=false;$('run-touch').classList.remove('active')});
$('fire-touch').addEventListener('pointerdown',e=>{e.preventDefault();touch.fire=true;shoot()});$('fire-touch').addEventListener('pointerup',()=>touch.fire=false);$('fire-touch').addEventListener('pointercancel',()=>touch.fire=false);
$('reload-touch').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
const stick=$('move-stick');let stickPointer=null;function stickInput(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=(e.clientX-cx)/(r.width*.4),dy=(cy-e.clientY)/(r.height*.4),mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}gamepadMove={x:dx,y:dy}}
stick.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickInput(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)stickInput(e)});function resetStick(e){if(e.pointerId===stickPointer){gamepadMove={x:0,y:0};stickPointer=null}}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
// Combine virtual stick values with keyboard axes.
const rawInputAxis=inputAxis;inputAxis=function(){let v=rawInputAxis();return{f:Math.abs(gamepadMove.y)>.12?gamepadMove.y:v.f,t:Math.abs(gamepadMove.x)>.12?gamepadMove.x:v.t}};
makeWorld();camera={x:W/2,y:H/2};resize();draw(0);
})();
</script>
</body>
</html>

