Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -8,4 +8,35 @@
 <div class="hud" id="hud"><div class="topbar"><div class="brand">LAST <span>/</span> LIGHT</div><div class="wavebox"><div class="eyebrow">NIGHT <span id="wn">01</span> / 04</div><div class="wave" id="wt">THE HOLLOW</div><div class="sub" id="kills">0 / 7 REMAINING</div></div><div class="topright"><div class="status"><i></i> SIGNAL LOST</div><button class="iconbtn" id="pause">Ⅱ</button></div></div>
 <div class="bottom"><div class="stats"><div class="statline"><span class="label">VITALS</span><span class="value" id="hv">100%</span></div><div class="bar"><i id="hb"></i></div><div class="statline"><span class="label">STAMINA</span><span class="value" id="sv">100%</span></div><div class="bar"><i id="sb"></i></div></div><div class="weapon"><div class="weapon-type">SIDEARM / 9MM</div><div class="weapon-name">M1911</div><div class="ammo-count"><strong id="ammo">15</strong> <span>/ <b id="reserve">90</b></span></div></div><div class="objective">OBJECTIVE<br><b>CLEAR THE GROUNDS</b><br><span>KEEP MOVING. STAY ALIVE.</span></div></div></div>
 <div class="toast" id="toast"></div><div class="overlay" id="overlay"><section class="panel"><div class="kicker" id="kicker">NORTH COUNTY · 02:17 AM</div><h1 id="title">LAST<br><em>LIGHT</em></h1><p class="subtitle" id="subtitle">The road is gone. The radio is dead.<br>Something is moving in the dark.</p><div class="rule"></div><div class="story" id="story">Four signal flares are burning beyond the cemetery. Reach the chapel and light them all.<br><br>One magazine. A handful of rounds. Make every shot count.</div><div class="buttons"><button class="primary" id="start">ENTER THE HOLLOW&nbsp; ↗</button><button class="secondary" id="notes">FIELD NOTES</button></div></section><div class="controls-note"><span><b class="key">W / S</b> MOVE</span><span><b class="key">A / D</b> TURN</span><span><b class="key">RMB</b> AIM</span><span><b class="key">LMB</b> FIRE</span><span><b class="key">R</b> RELOAD</span></div></div>
 <div class="mobile" id="mobile"><div class="stick" id="stick"></div><div class="actions"><button class="touchbtn" id="run">RUN</button><button class="touchbtn" id="aim">AIM</button><button class="touchbtn fire" id="fire">FIRE</button><button class="touchbtn" id="reload">RLD</button></div></div></main><script>
+(()=>{'use strict';
+const $=id=>document.getElementById(id),canvas=$('screen'),ctx=canvas.getContext('2d'),game=$('game'),W=1900,H=1450,TAU=Math.PI*2;
